-- UP : onglet Documents (Système) — Inbox + tri par l'IA. Tous les documents existants naissent « a_trier ».
-- Le tri écrit : proposition (jsonb) puis, à la confirmation, type / date / tiers / référence / montant / résumé + file_name renommé.
alter table public.documents add column if not exists statut_tri text not null default 'a_trier', add column if not exists type_document text, add column if not exists date_document date, add column if not exists tiers text, add column if not exists reference text, add column if not exists montant_ttc_cts integer, add column if not exists resume text, add column if not exists proposition jsonb, add column if not exists trie_le timestamptz;
alter table public.documents add constraint documents_statut_tri_check check (statut_tri in ('a_trier','propose','classe')) not valid;
create index if not exists documents_statut_tri_idx on public.documents (company_id, statut_tri);
-- DOWN (commentaire) : drop index if exists documents_statut_tri_idx; alter table public.documents drop constraint if exists documents_statut_tri_check, drop column if exists statut_tri, drop column if exists type_document, drop column if exists date_document, drop column if exists tiers, drop column if exists reference, drop column if exists montant_ttc_cts, drop column if exists resume, drop column if exists proposition, drop column if exists trie_le;
